async function doPrune(){try{let d=await jpost('/api/prune?keep='+retention+'&dry=1',{});if(!d.removed){alert('Silinecek kayıt yok.');return;}if(!confirm(fmt(d.removed)+' kayıt ('+d.cutoff+' tarihinden öncesi) silinecek, '+fmt(d.kept)+' kayıt kalacak. Devam edilsin mi? (Gerekçe sorulacak; yönetici ise talep süper-yönetici onayına gider.)'))return;let reason=prompt(me.superadmin?'Silme gerekçesi (en az 10 karakter; denetim kaydına yazılır):':'Silme gerekçesi (en az 10 karakter; talep süper-yöneticinin onayına gider):');if(reason===null)return;let r=await jpost('/api/prune?keep='+retention,{reason});if(r.pending){alert('Temizlik talebi süper-yöneticinin onayına gönderildi (talep '+r.id+'). Onaylanmadan hiçbir şey silinmez.');}else{await loadShared();await refresh();$('importStatus').textContent=fmt(r.removed)+' eski kayıt silindi.';}refreshBadge();}catch(e){alert(e.message);}}
for(let b of document.querySelectorAll('.prune'))b.onclick=doPrune;


