async function loadUsers(){let r=await api('/api/users');$('usersTable').innerHTML='<table><thead><tr><th>Kullanıcı</th><th>Rol</th><th>Durum</th><th>Son giriş</th><th>E-posta (bildirim)</th><th>Ekleyen</th><th></th></tr></thead><tbody>'+(r.users.length?r.users.map(u=>{let self=u.username===me.username;return '<tr><td>'+esc(u.username)+'</td><td><select data-role="'+esc(u.username)+'"'+(self?' disabled':'')+'>'+['viewer','admin','superadmin'].map(v=>'<option value="'+v+'"'+(u.role===v?' selected':'')+'>'+ROLES[v]+'</option>').join('')+'</select></td><td>'+(u.disabled?'Kapalı':'Açık')+'</td><td>'+(u.lastLogin?esc(when(u.lastLogin)):'—')+'</td><td style="text-align:left">'+(u.notifyAddress?esc(u.notifyAddress)+(u.email?'':' <span class="sub">(kullanıcı adı)</span>'):'—')+' <button data-email="'+esc(u.username)+'" data-current="'+esc(u.email||'')+'">Düzenle</button></td><td>'+esc(u.createdBy||'')+'</td><td>'+(self?'':'<button data-toggle="'+esc(u.username)+'" data-op="'+(u.disabled?'enable':'disable')+'">'+(u.disabled?'Aç':'Kapat')+'</button> <button data-delete="'+esc(u.username)+'">Sil</button>')+'</td></tr>';}).join(''):'<tr><td colspan="7">Henüz kişi hesabı yok. Aşağıdan ekleyin.</td></tr>')+'</tbody></table><p class="sub">“admin” hesabı Render ortam değişkenindeki ADMIN_PASSWORD ile girilen acil durum hesabıdır; günlük kullanım için kişi hesapları kullanın.</p><p class="sub">'+(r.mail&&r.mail.enabled?'E-posta bildirimi <b>açık</b> ('+(r.mail.transport==='graph'?'Microsoft Graph':'SMTP')+', gönderen: '+esc(r.mail.from)+'). Bildirimler: '+esc((r.mail.notifyOn||[]).join(', '))+'. Kayıtta e-postası olmayan kullanıcılar bildirim almaz. <button data-mailtest="1">Test e-postası gönder</button> '+(r.mail.summary&&r.mail.summary.enabled?'<br>Günlük özet: hafta içi her gün '+esc(r.mail.summary.time)+' (İstanbul), e-postası olan herkese. <a href="/api/summary-preview" target="_blank" rel="noopener"><button type="button">Önizle</button></a> <button data-summarytest="1">Günlük özeti bana gönder</button> <button data-summarytest="supers">Süper-yöneticilere gönder</button>':'<br>Günlük özet kapalı (NOTIFY_ON).'):'E-posta bildirimi <b>kapalı</b>. '+(r.mail&&r.mail.missing&&r.mail.missing.length?'Sunucunun görmediği / eksik değişkenler: <b>'+esc(r.mail.missing.join(', '))+'</b>. Render → Environment bölümünde ekleyip kaydedin; servis yeniden başlayınca açılır.':'Açmak için Render ortam değişkenlerine Microsoft Graph (GRAPH_TENANT_ID, GRAPH_CLIENT_ID, GRAPH_CLIENT_SECRET, MAIL_FROM) veya SMTP ayarlarını ekleyin (README: E-posta bildirimi).'))+'</p>';}
async function loadAudit(){try{let r=await api('/api/audit?limit=200&event='+encodeURIComponent($('auditEvent').value));$('auditTable').innerHTML=r.entries.length?'<table><thead><tr><th>Zaman</th><th>Kullanıcı</th><th>Olay</th><th>IP</th><th>Ayrıntı</th></tr></thead><tbody>'+r.entries.map(e=>'<tr><td>'+esc(when(e.ts))+'</td><td>'+esc(e.user||'—')+'</td><td>'+esc(EVENTS[e.event]||e.event)+'</td><td>'+esc(e.ip||'')+'</td><td style="text-align:left;white-space:normal;min-width:260px">'+esc(Object.entries(e.detail||{}).filter(([,v])=>v!==''&&v!=null&&!(Array.isArray(v)&&!v.length)).map(([k,v])=>k+': '+(Array.isArray(v)?v.join('; '):v)).join(' · '))+'</td></tr>').join('')+'</tbody></table>':'<div class="empty">Kayıt yok.</div>';}catch(e){$('auditTable').textContent=e.message;}}
