$('usersTable').onclick=async e=>{let em=e.target.dataset.email;if(em!==undefined&&e.target.tagName==='BUTTON'){let v=prompt(em+' için bildirim e-posta adresi (boş bırakırsan silinir):',e.target.dataset.current||'');if(v!==null)manageUser({op:'email',username:em,email:v.trim()},em+' e-posta adresi güncellendi.');return;}if(e.target.dataset.summarytest){$('usersStatus').textContent='Günlük özet hazırlanıyor ve gönderiliyor…';try{let sup=e.target.dataset.summarytest==='supers',r=await jpost('/api/summary-test'+(sup?'?to=supers':''),{});$('usersStatus').textContent=sup?'Günlük özet '+r.sent+'/'+r.total+' Süper-yöneticiye gönderildi'+(r.failed.length?' (hata: '+r.failed.join('; ')+')':'.'):'Günlük özet '+r.to+' adresine gönderildi'+(r.day?' ('+dayMonth(r.day)+' günü).':'.');}catch(err){$('usersStatus').textContent=err.message;}return;}if(e.target.dataset.mailtest){$('usersStatus').textContent='Test e-postası gönderiliyor…';try{let r=await jpost('/api/mail-test',{});$('usersStatus').textContent='Test e-postası gönderildi: '+r.to;}catch(err){$('usersStatus').textContent=err.message;}return;}let del=e.target.dataset.delete;if(del){if(confirm(del+' hesabı kalıcı olarak silinecek ve bir daha giriş yapamayacak. Geçmiş işlemleri denetim kaydında kalır. Devam edilsin mi?'))manageUser({op:'delete',username:del},del+' hesabı silindi.');return;}let name=e.target.dataset.toggle;if(name)manageUser({op:e.target.dataset.op,username:name},name+(e.target.dataset.op==='disable'?' hesabı kapatıldı.':' hesabı açıldı.'));};
$('nuGen').onclick=()=>{const chars='abcdefghjkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789',a=crypto.getRandomValues(new Uint32Array(18));$('nuPass').value=[...a].map(n=>chars[n%chars.length]).join('');};
