// ---- Silme talepleri (Yönetici: kendi talepleri; Süper-yönetici: tümü, onay/ret)
const REQ_STATUS={pending:'Bekliyor',approved:'Onaylandı',rejected:'Reddedildi',cancelled:'İptal edildi'};
async function refreshBadge(){if(!isAdmin)return;try{let r=await api('/api/delete-requests');$('reqBadge').textContent=r.pending;$('reqBadge').classList.toggle('hidden',!r.pending);$('menuBadge').textContent=r.pending;$('menuBadge').classList.toggle('hidden',!r.pending);}catch(e){}}
async function loadRequests(){let r=await api('/api/delete-requests');$('reqTable').innerHTML=r.requests.length?'<table><thead><tr><th>Talep tarihi</th><th>Talep eden</th><th>Kapsam</th><th>Gerekçe</th><th>Durum</th><th></th></tr></thead><tbody>'+r.requests.map(q=>{let scope=(q.kind==='prune'?'Eski kayıt temizliği · ':'')+(q.channel||'Tüm kanallar')+' · '+(q.start==='1970-01-01'?'… – ':q.start+' – ')+q.end,impact=q.status==='pending'&&q.impact?'<br><span class="sub">Şu an '+fmt(q.impact.removed)+' kayıt etkilenir</span>':q.result?'<br><span class="sub">'+fmt(q.result.removed)+' kayıt silindi</span>':'',decided=q.decidedBy&&q.status!=='pending'?'<br><span class="sub">'+esc(q.decidedBy)+(q.note?': '+esc(q.note):'')+(q.auto?' (doğrudan)':'')+'</span>':'',acts='';if(q.status==='pending'){if(me.superadmin&&q.requestedBy!==me.username)acts+='<button data-approve="'+esc(q.id)+'" class="primary">Onayla</button> <button data-reject="'+esc(q.id)+'">Reddet</button> ';if(q.requestedBy===me.username||me.superadmin)acts+='<button data-cancel="'+esc(q.id)+'">İptal</button>';}return '<tr><td>'+esc(when(q.requestedAt))+'</td><td>'+esc(q.requestedBy)+'</td><td style="text-align:left;white-space:normal">'+esc(scope)+impact+'</td><td class="req-reason">'+esc(q.reason)+'</td><td>'+REQ_STATUS[q.status]+decided+'</td><td>'+acts+'</td></tr>';}).join('')+'</tbody></table>':'<div class="empty">Silme talebi yok.</div>';$('reqBadge').textContent=r.pending;$('reqBadge').classList.toggle('hidden',!r.pending);$('menuBadge').textContent=r.pending;$('menuBadge').classList.toggle('hidden',!r.pending);}
$('reqBtn').onclick=()=>{$('reqStatus').textContent='';$('reqHelp').textContent=me.superadmin?'Yöneticilerin silme talepleri burada onayını bekler. Gerekçeyi ve etkilenecek kayıt sayısını değerlendirip onayla veya reddet; onaylanınca silme anında yapılır ve öncesinde anlık görüntü alınır.':'Silme taleplerin süper-yönetici onayına gider. Onaylanmadan hiçbir şey silinmez; bekleyen talebini iptal edebilirsin.';$('reqDlg').showModal();loadRequests().catch(e=>$('reqStatus').textContent=e.message);};
async function decideRequest(op,id,note){try{let r=await jpost('/api/delete-requests',{op,id,note});$('reqStatus').textContent=op==='approve'?fmt(r.result.removed)+' kayıt silindi.':op==='reject'?'Talep reddedildi.':'Talep iptal edildi.';await loadRequests();if(op==='approve'){await loadShared();await refresh();}}catch(e){$('reqStatus').textContent=e.message;await loadRequests().catch(()=>{});}}
$('reqTable').onclick=e=>{let d=e.target.dataset;if(d.approve){if(confirm('Bu silme talebini onaylıyor musun? Kayıtlar hemen silinir (öncesinde anlık görüntü alınır).'))decideRequest('approve',d.approve,'');}else if(d.reject){let note=prompt('Reddetme nedeni (isteğe bağlı):');if(note!==null)decideRequest('reject',d.reject,note);}else if(d.cancel){if(confirm('Talep iptal edilsin mi?'))decideRequest('cancel',d.cancel,'');}};

