$('compare').onchange=()=>{for(let id of ['cmpStartWrap','cmpEndWrap'])$(id).classList.toggle('hidden',$('compare').value!=='custom');refresh();};$('cmpStart').onchange=refresh;$('cmpEnd').onchange=refresh;
$('preset').onchange=()=>{let v=$('preset').value;if(!v)return;let r=presetRange(v,lastCompletedDay());$('start').value=r[0];$('end').value=r[1];refresh();};for(let id of ['start','end'])$(id).addEventListener('change',()=>{$('preset').value='';});$('hourMetric').onchange=()=>{if(current)renderHourly(current);};
