 let wide=view==='channel',W=wide?1150:570,L=44,R=W-50,T=14,B=200,up=Math.max(100,...vals.filter(x=>x!=null),...cv.filter(x=>x!=null)),X=i=>len===1?(L+R)/2:L+i*(R-L)/(len-1),Y=x=>B-(B-T)*x/up,s='';
 if(v.f.granularity==='day'&&len>1){let bw=(R-L)/(len-1);P.forEach((p,i)=>{let d=new Date(p.name+'T12:00:00Z').getUTCDay();if(d===0||d===6){let x0=Math.max(L,X(i)-bw/2),x1=Math.min(R,X(i)+bw/2);s+='<rect x="'+x0.toFixed(1)+'" y="'+T+'" width="'+(x1-x0).toFixed(1)+'" height="'+(B-T)+'" fill="#f1f4fa"/>';}});}
