 let segs=(arr)=>{let out=[],cur=[];arr.forEach((x,i)=>{if(x==null){if(cur.length)out.push(cur);cur=[];}else cur.push([X(i),Y(x),i]);});if(cur.length)out.push(cur);return out;};
 for(let g of segs(cv))if(g.length>1)s+='<polyline fill="none" stroke="#94a3b8" stroke-width="2" stroke-dasharray="6 4" points="'+g.map(p=>p[0].toFixed(1)+','+p[1].toFixed(1)).join(' ')+'"><title>Karşılaştırma dönemi</title></polyline>';
